arguments.command:
curl -s https://slack.com/api/conversations.list -d token=<TOKEN> -d types=public_channel,private_channel -d limit=1000 | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERROR:', d); sys.exit(1)
for c in d['channels']:
    if 'incident' in c['name']:
        print(c['id'], c['name'])
"

